RESIDUE_MASSES = {
    'A': 71, 'C': 103, 'D': 115, 'E': 129,
    'K': 128, 'P': 97, 'R': 156,
}


def _segments(seq):
    """Return list of (start, end) one-based inclusive elementary segments."""
    n = len(seq)
    cuts = []
    for i in range(n):
        r = seq[i]
        if r in ('K', 'R'):
            if i + 1 < n and seq[i + 1] == 'P':
                continue
            cuts.append(i)
    # Always cut at the end.
    cuts.append(n - 1)
    segments = []
    prev = 0
    for c in cuts:
        segments.append((prev + 1, c + 1))
        prev = c + 1
    return segments


def _emit_segments(segments):
    """Yield (start, end) for elementary segments and adjacent joined pairs."""
    m = len(segments)
    for i in range(m):
        s, e = segments[i]
        if e - s + 1 >= 2:
            yield (s, e)
        if i + 1 < m:
            s2, e2 = segments[i + 1]
            if e2 - s + 1 >= 2:
                yield (s, e2)


def _fragments(masses):
    """Prefix and suffix sums of length 1..n-1 (multiset)."""
    n = len(masses)
    ions = []
    for k in range(1, n):
        ions.append(sum(masses[:k]))
    for k in range(1, n):
        ions.append(sum(masses[n - k:]))
    return ions


def candidate_fragments(proteins, modifications):
    for protein in proteins:
        pid = protein['id']
        seq = protein['sequence']
        for kind, s in (('target', seq), ('decoy', seq[::-1])):
            segments = _segments(s)
            for start, end in _emit_segments(segments):
                base = list(s[start - 1:end])
                # Unmodified variant.
                yield (f"{pid}/{kind}:{start}-{end}:none", kind,
                       _fragments([RESIDUE_MASSES[r] for r in base]))
                # Modified variants: at most one modification per variant.
                for mod in modifications:
                    if mod['residue'] in base:
                        for pos in range(len(base)):
                            if base[pos] == mod['residue']:
                                masses = [RESIDUE_MASSES[r] for r in base]
                                masses[pos] += mod['shift']
                                if masses[pos] > 0:
                                    yield (
                                        f"{pid}/{kind}:{start}-{end}:"
                                        f"{mod['name']}@{start + pos}",
                                        kind, _fragments(masses))

def match_score(ions, peaks, tolerance):
    """Return lexicographically best (count, intensity, -error) over one-to-one
    ion/peak matches. Equal ion masses and equal peak masses are separate entries."""
    ions = list(ions)
    peaks = list(peaks)
    n = len(ions)
    m = len(peaks)
    best = (0, 0, 0)

    # Greedy over ions: for each ion pick the best available peak. This is not
    # globally optimal in general, so we do a full search over matchings via
    # recursion with memoization on (ion_index, used_peaks_bitmask).
    from functools import lru_cache

    peak_mass = [p['mass'] for p in peaks]
    peak_int = [p['intensity'] for p in peaks]

    @lru_cache(maxsize=None)
    def rec(i, used):
        if i == n:
            return (0, 0, 0)
        best_local = None
        for j in range(m):
            if used & (1 << j):
                continue
            if abs(ions[i] - peak_mass[j]) <= tolerance:
                err = abs(ions[i] - peak_mass[j])
                sub = rec(i + 1, used | (1 << j))
                cand = (1 + sub[0], peak_int[j] + sub[1], -(err + (-sub[2])))
                if best_local is None or cand > best_local:
                    best_local = cand
        if best_local is None:
            best_local = rec(i + 1, used)
        return best_local

    return rec(0, 0)

from runtime import build, read

from .candidate_fragments import candidate_fragments
from .peak_matching import match_score


def transform(payload, contract):
    request = payload["request"]
    proteins = request["proteins"]
    modifications = request["modifications"]
    spectra = request["spectra"]
    tolerance = request["tolerance"]

    candidates = list(candidate_fragments(proteins, modifications))
    candidate_count = len(candidates)

    winners = []
    for spectrum in spectra:
        sid = spectrum["id"]
        peaks = spectrum["peaks"]
        best = None
        for candidate_id, kind, ions in candidates:
            score = match_score(ions, peaks, tolerance)
            key = (score, 0 if kind == "target" else 1, candidate_id)
            if best is None or key > best[0]:
                best = (key, candidate_id, kind, score)
        _, candidate_id, kind, score = best
        winners.append({
            "spectrum": sid,
            "candidate": candidate_id,
            "kind": kind,
            "score": list(score),
        })

    # Rank winners by descending score tuple, then ascending spectrum ID.
    winners.sort(key=lambda w: (tuple(-x for x in w["score"]), w["spectrum"]))

    decoys = 0
    targets = 0
    for w in winners:
        if w["kind"] == "decoy":
            decoys += 1
        else:
            targets += 1
        w["fdr_numerator"] = decoys
        w["fdr_denominator"] = max(1, targets)

    return {"candidate_count": candidate_count, "winners": winners}


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

